package solution

func NewPowersOfThree() func() (uint64, bool) {
	next := uint64(1)
	done := false
	return func() (uint64, bool) {
		if done {
			return 0, false
		}
		value := next
		if next > ^uint64(0)/3 {
			done = true
		} else {
			next *= 3
		}
		return value, true
	}
}

func PowersOfThree(n int) []uint64 {
	if n <= 0 {
		return []uint64{}
	}
	out := make([]uint64, 0, n)
	next := NewPowersOfThree()
	for len(out) < n {
		value, ok := next()
		if !ok {
			break
		}
		out = append(out, value)
	}
	return out
}
